  await figma.setCurrentPageAsync(page);
  const f1 = await figma.getNodeByIdAsync("29:73");
  const f2 = await figma.getNodeByIdAsync("31:85");

  function hotspot(parent, name, x, y, w, h, destId, transition) {
    const r = figma.createRectangle();
    r.name = name;
    r.resize(w, h);
    r.x = x; r.y = y;
    r.fills = [];
    parent.appendChild(r);
    r.reactions = [{
      trigger: {type: "ON_CLICK"},
      action: {type: "NODE", destinationId: destId, navigation: transition || "NAVIGATE", transition: {type: "SMART_ANIMATE", duration: 0.3, easing: {type: "EASE_IN_AND_EASE_OUT"}}, resetVideoPosition: false, resetComponents: false, resetInteractions: false}
    }];
    return r;
  }

  // 01: Get Started button -> 02_Home
  hotspot(f1, "Hotspot · Get Started", 20, 692, 335, 56, f2.id, "NAVIGATE");

  // 02: balance card -> 03_Wallet
  hotspot(f2, "Hotspot · Balance", 20, 130, 335, 190, "33:138", "NAVIGATE");
  // 02: See all -> 03_Wallet
  hotspot(f2, "Hotspot · See all", 280, 488, 75, 30, "33:138", "NAVIGATE");
  // 02: plus (new payment) -> 05_Payment
  hotspot(f2, "Hotspot · New payment", 307, 76, 48, 48, "36:6", "NAVIGATE");

  return "hotspots 01+02 added";
} catch (e) { return "ERROR: " + e.message; }

